<script setup>import{onMounted,ref}from'vue';import{supabase}from'../supabase.js';import{useContract}from'../composables/useContract.js';import BottomNav from'../components/BottomNav.vue';const{loading,error,membership,load}=useContract(),rows=ref([]);const money=v=>new Intl.NumberFormat('th-TH',{minimumFractionDigits:2}).format(Number(v||0));async function init(){if(!(await load()))return;const{data,error:e}=await supabase.from('installments').select('id,installment_no,amount,status,installment_slips(id,amount,payer_no)').eq('contract_id',membership.value.contract_id).order('installment_no');if(e)throw e;rows.value=(data||[]).filter(x=>x.installment_slips?.length)}onMounted(init)</script><template><main class="app-shell"><header class="page-head"><RouterLink to="/dashboard">‹</RouterLink><h1>ประวัติชำระ</h1></header><div v-if="loading" class="card state">กำลังโหลด...</div><div v-else-if="error" class="card alert error">{{error}}</div><section v-else class="card"><div v-if="!rows.length" class="state">ยังไม่มีประวัติสลิป</div><div v-for="i in rows" :key="i.id" class="status-row"><div><b>งวดที่ {{i.installment_no}}</b><small>{{i.installment_slips.length}} สลิป · {{money(i.amount)}} บาท</small></div><em :class="i.status">{{i.status}}</em><RouterLink :to="'/payment/'+i.id">›</RouterLink></div></section><BottomNav/></main></template>
